CSS='''*{box-sizing:border-box}body{margin:0;background:#f5f5ef;color:#20352f;font:16px/1.85 system-ui,-apple-system,"Segoe UI","Microsoft YaHei",sans-serif}a{color:#116657;text-underline-offset:4px}header{background:#163c34;color:#f8faf4;padding:48px max(24px,calc((100vw - 1060px)/2)) 36px}header p{color:#c8ded4;max-width:760px}h1{font-size:clamp(28px,4vw,43px);line-height:1.3;margin:12px 0}h2{font-size:24px;margin:0 0 18px;letter-spacing:-.5px}h3{font-size:18px;margin:22px 0 8px}p{margin:10px 0 18px}.eyebrow{font-size:12px;letter-spacing:2px;color:#bdd8c9}nav{display:flex;gap:8px;flex-wrap:wrap;max-width:1108px;margin:auto;padding:20px 24px}nav a{padding:8px 13px;text-decoration:none;border-radius:7px;background:#e8ece5;font-size:14px}nav a[aria-current=page]{background:#176b59;color:white}main{max-width:1108px;margin:auto;padding:6px 24px 44px}section{background:#fff;padding:30px 34px;border:1px solid #e0e5dc;border-radius:12px;margin:18px 0}.lead{font-size:19px}.note{border-left:4px solid #b5862c;background:#faf4e5;padding:16px 20px;margin:20px 0}.good{border-left-color:#267660;background:#edf6ef}.tag{display:inline-block;font-size:12px;font-weight:650;border-radius:4px;padding:2px 8px;background:#e8f2e9;color:#235f40}.tag.plan{background:#fff0d6;color:#835500}.tag.code{background:#e9edf6;color:#405b83}.tag.fail{background:#fbe9e5;color:#933e32}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px}.block{padding:20px;background:#f4f7f1;border-radius:8px}.block strong{display:block;font-size:18px}.flow{display:grid;gap:10px}.flow a,.flow>div:not(.arrow){display:block;padding:16px 20px;background:#edf4ee;border-radius:7px;text-decoration:none}.flow span{color:#536960;font-size:14px;display:block}.arrow{text-align:center;color:#647d70;font-size:20px;line-height:1}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;vertical-align:top;padding:12px 14px;border-bottom:1px solid #e4e9e1}th{background:#eff3ec;white-space:nowrap}code{font:13px/1.65 Consolas,monospace;overflow-wrap:anywhere;background:#eff2ed;padding:2px 5px;border-radius:4px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#173b33;color:#eff8ef;padding:20px;border-radius:8px;font:14px/1.7 Consolas,monospace}details{border-top:1px solid #e2e8df;padding:15px 0}summary{cursor:pointer;font-weight:650}details p{margin:14px 0 5px}.metric{font-size:38px;font-weight:700;line-height:1.4;display:block;color:#176b59}.small{font-size:13px;color:#5c7067}.step-no{font-size:13px;letter-spacing:2px;color:#38705b}.footer{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;padding:24px 0}.source{font-size:13px}ul,ol{padding-left:24px}li{margin:7px 0}.equation{font-size:clamp(17px,3vw,24px);font-weight:650;padding:18px;background:#edf4ee;border-radius:7px;text-align:center}.bar{height:12px;background:#dce9dd;margin:9px 0 16px;border-radius:4px}.bar b{display:block;height:100%;background:#347961;border-radius:4px}button{font:inherit;background:#e8eee6;border:0;border-radius:6px;padding:8px 15px;cursor:pointer}a:focus-visible,summary:focus-visible,button:focus-visible{outline:3px solid #bc902c;outline-offset:4px}@media(max-width:640px){header{padding:32px 20px}main{padding:0 14px 24px}section{padding:22px 18px}nav{padding:15px 14px;gap:6px}nav a{font-size:12px;padding:7px 9px}th,td{padding:10px;min-width:105px}.grid{grid-template-columns:1fr}}@media print{body{background:white;font-size:11pt}header{background:white;color:#173b33;padding:0}header p,.eyebrow{color:#365748}nav,.footer,button{display:none}main{max-width:none;padding:0}section{border:0;padding:12px 0;break-inside:avoid}pre{color:#173b33;background:#f0f4ef}a{color:inherit}.note{background:#fafafa}details{break-inside:avoid}}'''

def page(i,content):
    filename,title,sub=CHAPTERS[i]
    nav=''.join(f'<a href="{f}" '+('aria-current="page"' if j==i else '')+f'>{j+1:02d} · {t}</a>' for j,(f,t,_) in enumerate(CHAPTERS))
    nav += '<a href="06-stage-b.html">B 阶段 · 数据剖析与建模</a>'
    nav += '<a href="07-stage-c.html">C 阶段 · 闭环实测</a><a href="08-fhir.html">FHIR 资源流转</a><a href="09-reliability.html">D阶段 · 异常恢复</a><a href="10-scale.html">E阶段 · 规模实测</a>'
    prev=f'<a href="{CHAPTERS[i-1][0]}">← 上一章：{CHAPTERS[i-1][1]}</a>' if i else '<span>从业务问题开始，再看数据与实现。</span>'
    next=f'<a href="{CHAPTERS[i+1][0]}">下一章：{CHAPTERS[i+1][1]} →</a>' if i<4 else '<a href="01-overview.html">返回第一章 →</a>'
    doc=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{i+1:02d} · {title} | 医疗数据项目复习</title><style>{CSS}</style></head><body><header><div class="eyebrow">MEDICAL DATA ENGINEERING / SYNTHEA · 2026.09.18</div><h1>{i+1:02d} / {title}</h1><p>{sub}。这是一份学习与规划材料，明确区分已核实事实、已有代码和待实施设计。</p></header><nav aria-label="章节目录">{nav}</nav><main><div class="note good">已暂停后续开发，等待用户额度恢复。C 阶段核心闭环已通过：45 个测试、17 项核验通过。<a href="07-stage-c.html">查看最新实测报告</a> · <a href="../PROGRESS.md">进度与恢复记录</a>。</div>{content}<footer class="footer">{prev}{next}</footer><p class="small">离线阅读 · 无需安装依赖 · 可使用浏览器打印功能保存为 PDF。技术状态为 2026-09-18 快照。</p></main></body></html>'''
    (ROOT/filename).write_text(doc,encoding='utf-8')

page(0,'''<section><span class="tag plan">业务目标与规划</span><h2>把零散医疗记录，变成可以解释的数据服务</h2><p class="lead">回答一个具体问题：<strong>这个患者在哪次就诊中做了哪些检查？一共做了几次？最近一次是什么时候？</strong></p><p>源数据分散在患者、就诊、影像表中。项目负责接入、校验、标准化、关联、分层和查询，同时记录每次处理的来源与结果。它主要展示数据工程能力。</p><div class="grid"><div class="block"><strong>业务结果</strong>患者检查概览、按日期及模态统计检查量。</div><div class="block"><strong>工程结果</strong>可重复运行、数量能对账、异常能定位。</div><div class="block"><strong>复习目标</strong>讲清输入规模、实际产出、流转和问题处理。</div></div></section>
<section><h2>项目整体关系</h2><p class="small">下图展示业务主链路。三表至数据库/API 已实现；FHIR 新映射与后续 observations 接入仍待完成。点击节点查看细节。</p><div class="flow"><a href="02-data-flow.html#source"><strong>Synthea · 数据源</strong><span>patients / encounters / imaging_studies；observations 后续补充</span></a><div class="arrow" aria-hidden="true">↓</div><a href="02-data-flow.html#ods"><strong>ODS · 原始记录与来源</strong><span>按源表保存字段，加批次、源文件、校验值和行位置</span></a><div class="arrow" aria-hidden="true">↓</div><a href="02-data-flow.html#quality"><strong>标准化与质量处理</strong><span>检查键、时间和关联；区分有效、隔离、重复</span></a><div class="arrow" aria-hidden="true">↓</div><a href="02-data-flow.html#detail"><strong>DIM + DWD · 维度与事实</strong><span>患者维度 ｜ 就诊事实 ｜ 检查事实 ｜ 实例关联</span></a><div class="arrow" aria-hidden="true">↓</div><a href="02-data-flow.html#aggregate"><strong>DWS → ADS · 汇总与应用</strong><span>通用统计 → 患者检查概览 / 检查量分析</span></a><div class="arrow" aria-hidden="true">↓</div><a href="02-data-flow.html#serve"><strong>API / SQL / FHIR</strong><span>查询服务与标准化资源；FHIR 导出可从 DIM / DWD 直接映射</span></a></div><div class="note good">数据质量、批次日志和数量对账贯穿流程。Airflow 负责安排执行顺序；它不会代替清洗、建模或质量规则。</div></section>
<section><h2>这些技术各自做什么？</h2><div class="table-wrap"><table><thead><tr><th>组件</th><th>在项目中的职责</th><th>需要避免的误解</th></tr></thead><tbody><tr><td>Python / Pandas</td><td>读取数据、转换字段、质量检查和小规模批处理</td><td>代码可运行不代表数据语义正确</td></tr><tr><td>PostgreSQL</td><td>已作为新主链路落地和 API 查询源</td><td>建了表不代表已写入和核对数据</td></tr><tr><td>Parquet / Spark</td><td>列式文件存储；后续做批处理和同口径对照</td><td>使用 Spark 不等于已验证集群规模</td></tr><tr><td>FastAPI</td><td>把数仓结果按接口提供给应用</td><td>接口存在不代表后端整条链路已跑通</td></tr><tr><td>FHIR</td><td>按明确版本映射医疗交换资源</td><td>JSON 能输出不等于符合全部标准与业务语义</td></tr><tr><td>Airflow</td><td>调度任务、管理依赖与重试</td><td>自动重试不能弥补非幂等的数据写入</td></tr></tbody></table></div></section>
<section><h2>当前实际状态</h2><div class="table-wrap"><table><thead><tr><th>部分</th><th>证据与状态</th></tr></thead><tbody><tr><td><span class="tag">已核实</span> 环境与数据</td><td>F 盘新环境与独立本机 PostgreSQL 已就绪；使用 Synthea 官方合成样本。</td></tr><tr><td><span class="tag">已跑通</span> Synthea 主线</td><td>108 患者、5,571 就诊、413 检查、478 实例；文件分层、数据库发布与 API 已验证。</td></tr><tr><td><span class="tag">已验证</span> 可靠性</td><td>45 个测试、17 项样本核验通过；空输入问题已修复，重复加载与失败回滚通过。</td></tr><tr><td><span class="tag code">历史保留</span> 原 EMR 示例</td><td>仅 --legacy-emr 运行；旧流程的汇总与连接限制不代表新主线状态。</td></tr><tr><td><span class="tag plan">待继续</span> FHIR / Spark / Airflow</td><td>FHIR R4B摘要导出已通过；完整FHIR服务、Spark、Airflow及大规模数据库/API尚未验证；分级文件ETL见第十章。</td></tr></tbody></table></div><div class="note">2026-09-20已恢复；FHIR R4B摘要导出6092个资源已核验，见第八章。D阶段已新增13项测试并修复2个问题，E阶段已完成分级首测：千人ETL通过，万人生成成功但ETL受内存限制，详见第十章。</div></section>
<section><h2>如何阅读这五章</h2><ol><li>先用本章把握项目目的与技术分工。</li><li>第二章跟着教学示例看每层的输入和输出。</li><li>第三章用已下载样本的实数理解数量口径。</li><li>第四章按阶段理解要补什么、如何验收。</li><li>第五章组织面试回答，并区分实践和设计。</li></ol><p class="source">项目依据：<a href="../SYNTHEA_PROJECT_PLAN.md">完整规划</a> · <a href="../TASK_MEMORY.md">任务记忆</a> · <a href="https://synthea.org/">Synthea 官方网站</a></p></section>''')
print('Created chapter 1:',ROOT/CHAPTERS[0][0])

page(1,'''<section><span class="tag plan">数据流转 · 教学示例</span><h2>先认识记录的层级</h2><p class="lead">一位患者 → 多次就诊 → 多次检查 → 多个序列 → 多个影像实例。</p><p>本章使用虚构标识讲解，<strong>不是已下载数据中的真实行，也不是实测结果</strong>。示例：患者 P-DEMO 在就诊 E-DEMO 中有两次检查。检查 S-01 有两个 CT 实例，检查 S-02 有一个 MR 实例。</p><pre>患者 P-DEMO
└─ 就诊 E-DEMO
   ├─ 检查 S-01（CT）
   │  └─ 序列 SE-01 → 实例 I-01、I-02
   └─ 检查 S-02（MR）
      └─ 序列 SE-02 → 实例 I-03</pre><div class="equation">1 位患者 ≠ 1 次就诊 ≠ 2 次检查 ≠ 3 个实例</div></section>
<section id="source"><div class="step-no">STEP 01 / SOURCE</div><h2>接入：先认识表，再关联</h2><div class="table-wrap"><table><thead><tr><th>源表</th><th>本例记录</th><th>关联方式</th></tr></thead><tbody><tr><td>patients.csv</td><td>Id = P-DEMO；性别、出生日期等</td><td>患者键</td></tr><tr><td>encounters.csv</td><td>Id = E-DEMO；PATIENT = P-DEMO</td><td>通过 PATIENT 找患者</td></tr><tr><td>imaging_studies.csv</td><td>3 条实例行；Id 分别为 S-01、S-01、S-02</td><td>PATIENT → 患者，ENCOUNTER → 就诊；SERIES_UID / INSTANCE_UID 标识层级</td></tr></tbody></table></div><p><strong>需要做：</strong>保存原始包，盘点文件大小、行数、字段和校验值。先确认实际键的唯一性与一对多关系，再定义转换。</p><details><summary>为什么不直接把三个表 JOIN 之后统计行数？</summary><p>一位患者会匹配多条检查实例，JOIN 后出现多行是正常的一对多展开。如果此时 COUNT(*)，得到的是展开后的行数，不能说是患者数或检查数。应先选定目标粒度，再按对应键去重或聚合。</p></details></section>
<section id="ods"><div class="step-no">STEP 02 / ODS</div><h2>ODS：保存原始形态与来路</h2><p>计划为三张源表分别保留 ODS 数据。原始值与标准化值分开保存，便于重跑和排查。</p><pre>业务字段：Id、PATIENT、ENCOUNTER、DATE、SERIES_UID、INSTANCE_UID…
追溯字段：batch_id、source_file、source_sha256、source_row、ingested_at</pre><p><strong>本例输出：</strong>患者 ODS 1 行、就诊 ODS 1 行、影像 ODS 3 行。此时不把两条 S-01 当成重复检查删掉，它们是不同实例。</p><div class="note">“ODS 原样保留”是目标设计。原项目主流程实际在清洗后写 ODS，分步流程还存在不同处理方式；这部分语义需要在实施时统一。</div></section>
<section id="quality"><div class="step-no">STEP 03 / QUALITY</div><h2>校验：决定记录能否进入可信明细</h2><div class="grid"><div class="block"><strong>字段有效</strong>键不缺失，时间可解析，代码和字段类型符合约定。</div><div class="block"><strong>关系一致</strong>患者存在、就诊存在，检查所属患者与就诊所属患者一致。</div><div class="block"><strong>重复可解释</strong>相同实例重复导入需要去重；不同实例属于同一检查应保留。</div></div><p>通过的进入明细；不通过的保留源位置和原因；相同业务键却内容冲突的记录按明确策略处置。本例假定全部合格，仍保留 3 条实例。</p><details><summary>如果某条记录同时日期非法、患者键缺失，怎么计数？</summary><p>它可以触发两项规则，但在“隔离记录数”里只计一次。规则失败次数与失败记录数必须分开，否则对账会重复扣减。</p></details><details><summary>一次失败应该直接重跑吗？</summary><p>先判断原因：输入缺字段、关联错误等需要处理数据或配置；临时连接故障才可能靠重试恢复。写入还必须保证失败批次不会被当作成功结果发布。</p></details></section>
<section id="detail"><div class="step-no">STEP 04 / DIM + DWD</div><h2>维度描述“谁”，事实记录“发生了什么”</h2><div class="table-wrap"><table><thead><tr><th>计划模型</th><th>一行代表什么</th><th>本例输出</th></tr></thead><tbody><tr><td>患者维度</td><td>一位有效患者，统一的下游患者键</td><td>1 行；P-DEMO 映射为 PID-DEMO（仅示意）</td></tr><tr><td>就诊事实</td><td>一次就诊</td><td>1 行；E-DEMO 关联 PID-DEMO</td></tr><tr><td>检查事实</td><td>一次影像检查，按源检查键</td><td>2 行；S-01 / S-02</td></tr><tr><td>实例关联</td><td>一个实例到所属检查和序列的关系</td><td>3 行；保留 I-01、I-02、I-03 的来路</td></tr></tbody></table></div><p><strong>身份处理：</strong>患者标识映射必须跨表一致，否则关系会断裂。姓名、精确出生日期等直接标识信息限制流转，原始键映射留在受限追溯区。已有截断哈希只属于原型实现，不能宣称完全匿名或生产级隐私保护。</p><div class="note good">3 条实例 → 2 次检查，是粒度归并。实例仍有独立关联记录，不能把这次变化说成丢掉了 1 条脏数据。</div></section>
<section id="aggregate"><div class="step-no">STEP 05 / DWS → ADS</div><h2>先定义公共统计，再服务具体问题</h2><pre>DWS：患者检查统计（本例）
patient_key = PID-DEMO
exam_count = 2
modality_count = 2
latest_exam_time = 两次检查时间中的较晚值

ADS：患者检查概览
患者维度 LEFT JOIN 患者检查统计
→ 展示患者信息、检查次数、最近检查与检查列表入口</pre><p>没有检查的有效患者仍可保留在 ADS，检查次数填 0。不要使用内连接无意删除他们。跨模态统计要明确：一项检查有多个模态时，它可能出现在多个分组中。</p></section>
<section id="serve"><div class="step-no">STEP 06 / SERVICE</div><h2>对外查询，同时能向后追溯</h2><p>API 从患者维度、检查事实或 ADS 读取合适结果。FHIR 可以从 DIM / DWD 映射，不必先绕过所有汇总层。</p><p><strong>计划评审的语义：</strong>患者 → Patient；就诊 → Encounter；影像检查 → ImagingStudy；生命体征/检验观察 → Observation。具体字段、版本和校验规则需在实施前确定。</p><pre>应用中的“检查次数 = 2”
 → DWS 中 PID-DEMO 的汇总
 → DWD 中 S-01、S-02
 → 检查与实例关联 I-01、I-02、I-03
 → ODS 源表 + 文件校验值 + 行位置
 → 原始 Synthea 文件</pre><div class="note">本例是教学示意；C 阶段已实际实现三表关联及检查到源实例的 API 追溯，真实样本验证见最新报告。</div></section>
<section><h2>这一章应该能自己回答</h2><ul><li>为什么 Patient 资源数通常小于检查事实数？</li><li>为什么合法的影像实例不能只按检查 ID 去重删除？</li><li>为什么总检查数不能直接用多表 JOIN 后的行数？</li><li>为什么查询结果需要批次、源位置和稳定业务键？</li></ul><p class="source">字段含义参考：<a href="https://github.com/synthetichealth/synthea/wiki/CSV-File-Data-Dictionary">Synthea 官方 CSV 数据字典</a>。本章数仓结构为项目规划。</p></section>''')
print('Created chapter 2:',ROOT/CHAPTERS[1][0])

page(2,'''<section><span class="tag">本机已核实 · Synthea 官方合成样本</span><h2>先说数据来源，再说数据量</h2><p>已下载的是 Synthea 官方 CSV 样本，包含 <strong>18 个 CSV 文件</strong>，ZIP 压缩包为 <strong>5,960,866 字节（约 5.68 MiB）</strong>。下列数字来自本机文件清单，不是根据网站“100 人样本”的标题推算。</p><div class="grid"><div class="block"><span class="metric">108</span>患者表记录数</div><div class="block"><span class="metric">5,571</span>就诊表记录数</div><div class="block"><span class="metric">478</span>影像实例源记录数</div></div><p class="small">已盘点不等于已全部接入。本次探索仅适配患者和影像部分，就诊表尚未进入探索链路。数据为合成记录。</p></section>
<section><h2>478 → 413 → 96，发生了什么？</h2><p><strong>478 条影像实例记录</strong> · 源文件行数</p><div class="bar"><b style="width:100%"></b></div><p><strong>413 次影像检查</strong> · 按源检查标识归并</p><div class="bar"><b style="width:86.4%"></b></div><p><strong>96 位患者</strong> · 这些检查涉及的不同患者</p><div class="bar"><b style="width:20.1%"></b></div><p class="small">横条仅辅助比较记录数量；三个数的业务单位不同，不表示处理通过率或漏斗转化率。</p><div class="note good"><strong>少了 65 行，并不等于过滤了 65 条坏数据。</strong>478 条实例行归并到 413 个检查键，差值来自一项检查对应多条实例。96 是参与这些检查的患者数，不能说其余检查被删除。</div><p>患者表共有 108 位患者，其中 96 位出现在影像队列中，另外 12 位未进入当前影像队列。不能据此说他们没有任何其他就诊或医疗记录。</p></section>
<section><span class="tag">C 阶段当前产出</span><h2>现在已经落库的数量</h2><p>患者 DIM/DWS/ADS 各 108 行；就诊 5,571 行；检查 413 行；序列 413 行；实例 478 行；日×模态统计 401 组。ODS 共 6,157 条原始记录，按三张逻辑源表隔离。</p><p>12 位无影像患者保留为零检查；17 项完整样本核验全部通过。<a href="07-stage-c.html">查看数据库与 API 实测</a>。</p></section><section><h2>早期六列探索结果（历史对照）</h2><div class="table-wrap"><table><thead><tr><th>环节</th><th>数量</th><th>统计口径</th></tr></thead><tbody><tr><td>适配后 EMR 输入</td><td>413 行 / 73,211 字节</td><td>一次检查一行，六列基础字段加源检查标识</td></tr><tr><td>隔离 / 去重</td><td>0 / 0</td><td>只针对适配后 413 行，不包括上游实例归并</td></tr><tr><td>DWD 检查明细</td><td>413 行</td><td>已保留检查</td></tr><tr><td>DIM 患者</td><td>96 行</td><td>仅影像队列；早期仅覆盖影像队列；C 阶段已扩展为 108 位</td></tr><tr><td>DWS / ADS</td><td>各 96 行</td><td>一位影像队列患者一条汇总/概览</td></tr><tr><td>FHIR 探索输出</td><td>Patient 96 / Observation 413</td><td>资源数量已对账；把影像检查映射成 Observation 的语义仍需调整</td></tr></tbody></table></div><p>文件链路单次记录约 <strong>0.45 秒</strong>，属于很小样本的一次运行，不是稳定性能基准，也不能用来推算大规模吞吐量。这次早期实验不包含数据库/API；C 阶段已补数据库/API验证，Spark、Airflow仍待验证。</p><p class="source">本机证据：<a href="../../data/external/synthea/dataset_manifest.json">源数据清单</a> · <a href="../../output/runs/synthea-public/manifest.json">探索运行报告</a>。移动 HTML 到其他目录后这些证据链接可能失效；章节内容可独立阅读。</p></section>
<section><span class="tag plan">未来测试口径 · 以下数字仅作教学示意</span><h2>同一粒度才能做“守恒”对账</h2><p>假设有 1,000 条同粒度输入：40 条隔离、10 条去重、950 条保留。每条记录只归入一个处置类别。</p><div class="equation">1,000 输入 = 950 有效 + 40 隔离 + 10 去重</div><p>两条规则都失败的一条记录，只算一次隔离。同样，聚合到 200 位患者之后，不能再写“1,000 − 200 = 800 条数据丢失”。</p><details><summary>检查明细与患者汇总如何核对？</summary><p>当每次检查只属于一位患者时，DWS 每位患者的 exam_count 加总应等于 DWD 检查事实行数。患者维表应覆盖事实里的所有患者键。跨模态分组可能交叉，不能直接把分组加总当去重总数。</p></details><details><summary>JOIN 之后的数量增大一定是错误吗？</summary><p>不一定。一对多关联会正常展开；但维表键不唯一也可能错误放大结果。因此要先声明预期基数，检查主键唯一性、孤儿关联和 JOIN 前后行数。</p></details><details><summary>为什么有了质量报告还需要逐行异常明细？</summary><p>报告告诉你哪个批次、哪条规则失败；异常明细才能定位具体源文件和行、解释处理策略，并支持修复重跑。</p></details></section>
<section><h2>规模实测要留哪些数字？</h2><ul><li>数据规模：患者、就诊、检查、实例、文件、字节，分别计数。</li><li>阶段产出：接入、隔离、去重、明细、汇总、导出，明确单位。</li><li>执行条件：机器、Python/Java/库版本、并行度、代码与数据版本。</li><li>性能：数据生成、ETL、落地、查询分开计时，多次运行再给范围。</li><li>可靠性：重跑结果是否一致；失败批次是否影响上次成功结果。</li></ul><div class="note">约千位和万位患者的数据生成仍是计划，尚无对应规模实测结果。</div></section>''')
